/**
 * 首頁公告彈窗設定。JSON 檔案存法，跟其他 store 同一套模式。
 *
 * 只有一筆設定（不是清單），所以直接存一個物件。
 * enabled 關掉的時候前端就不會跳彈窗，不用刪掉內容——
 * 活動結束先關起來，下次要用再打開比較方便。
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const FILE = path.join(__dirname, "announcement.json");

const DEFAULT = {
  enabled: true,
  // 純圖片模式：整張圖就是廣告，點圖直接進商品頁，不放按鈕也不放文字
  image: "data:image/svg+xml;base64,",
  ctaLink: "/skill/viral-video-script",
  // 下面幾個欄位保留給「想用文字版公告」的情況，有填 image 時不會顯示
  title: "",
  heading: "",
  body: "",
  ctaText: "",
  updatedAt: new Date().toISOString(),
};

function load() {
  if (!fs.existsSync(FILE)) {
    save(DEFAULT);
    return { ...DEFAULT };
  }
  try {
    return { ...DEFAULT, ...JSON.parse(fs.readFileSync(FILE, "utf8")) };
  } catch {
    return { ...DEFAULT };
  }
}
function save(data) {
  fs.writeFileSync(FILE, JSON.stringify(data, null, 2), "utf8");
}

let announcement = load();

export function get() {
  return announcement;
}

export function update(input) {
  // 純圖片模式不需要標題，所以這裡不強制 heading——
  // 但如果兩者都空，公告會是一片空白，那才是真的沒意義
  const merged = { ...announcement, ...input };
  if (!merged.image && !String(merged.heading || "").trim()) {
    return { error: "圖片和標題至少要有一個。" };
  }
  announcement = {
    ...announcement,
    ...input,
    enabled: input.enabled !== undefined ? !!input.enabled : announcement.enabled,
    updatedAt: new Date().toISOString(),
  };
  save(announcement);
  return { item: announcement };
}
